def segwit_decode(expected_hrp, addr):
    hrp, data, spec_or_err = bech32_decode(addr)
    if hrp is None:
        return ('invalid_bech', spec_or_err)
    if hrp != expected_hrp:
        return ('wrong_hrp', hrp, spec_or_err)
    if not data:
        return ('no_data', spec_or_err)
    witver = data[0]
    decoded = convertbits(data[1:], 5, 8, False)
    if decoded is None:
        return ('bad_convertbits', witver, spec_or_err)
    if len(decoded) < 2 or len(decoded) > 40:
        return ('bad_len', witver, len(decoded), spec_or_err)
    if witver > 16:
        return ('bad_witver', witver, spec_or_err)
    if witver == 0 and len(decoded) not in (20, 32):
        return ('bad_v0_len', len(decoded), spec_or_err)
    if witver == 0 and spec_or_err != 'bech32':
        return ('wrong_encoding_for_v0', spec_or_err)
    if witver != 0 and spec_or_err != 'bech32m':
        return ('wrong_encoding_for_vN', witver, spec_or_err)
    return ('ok', witver, len(decoded), spec_or_err)

